// KDP paperback rules, deliberately limited to the existing 6 x 9 export.
export const BACK_COVER_LIMIT = 1500;
export const PAPER_CHOICES = {
  'bw-white': { label: 'Black-and-white on white paper', factor: 0.002252, min: 24, max: 828 },
  'bw-cream': { label: 'Black-and-white on cream paper', factor: 0.0025, min: 24, max: 776 },
  'standard-color': { label: 'Standard color on white paper', factor: 0.002252, min: 72, max: 600 },
  'premium-color': { label: 'Premium color on white paper', factor: 0.002347, min: 24, max: 828 },
} as const;
export type PaperChoice = keyof typeof PAPER_CHOICES;
export interface PaperbackCoverOptions { paper: PaperChoice; backText: string }

export function coverDimensions(pdfPages: number, paper: PaperChoice) {
  const choice = PAPER_CHOICES[paper];
  if (!choice || !Number.isSafeInteger(pdfPages) || pdfPages < 1) {
    throw new Error('The finished PDF has an invalid page count or paper choice.');
  }
  const printPages = Math.ceil(pdfPages / 2) * 2;
  if (printPages < choice.min || printPages > choice.max) {
    throw new Error(`${choice.label} requires ${choice.min}–${choice.max} pages for a 6 × 9 paperback. This PDF has ${pdfPages} pages (${printPages} for printing).`);
  }
  const spine = printPages * choice.factor;
  return { pdfPages, printPages, spine, width: 12.25 + spine, height: 9.25 };
}

export function characterCount(text: string) { return Array.from(text).length; }
export function limitBackText(text: string) { return Array.from(text).slice(0, BACK_COVER_LIMIT).join(''); }

// A quarter-inch inset preserves existing cover lettering without cropping.
export function frontPlacement(width: number, height: number) {
  if (!(width > 0 && height > 0)) throw new Error('The EPUB cover image has no usable dimensions.');
  const scale = Math.min(5.5 / width, 8.5 / height);
  const printWidth = width * scale;
  const printHeight = height * scale;
  return { width: printWidth, height: printHeight, dpi: 1 / scale };
}

import type JSZip from 'jszip';
import { createPaperbackCover } from 'book-pdf/cover';
import { extractEpubCover } from './epub-cover';
import { coverDimensions, frontPlacement, type PaperbackCoverOptions } from './paperback-cover';

export async function prepareFrontImage(blob: Blob) {
  const url = URL.createObjectURL(blob);
  try {
    const image = new Image();
    image.src = url;
    await image.decode();
    const placement = frontPlacement(image.naturalWidth, image.naturalHeight);
    // Preserve all artwork; only reduce oversized images, never invent detail.
    const scale = Math.min(1, 300 / placement.dpi);
    const canvas = document.createElement('canvas');
    canvas.width = Math.max(1, Math.round(image.naturalWidth * scale));
    canvas.height = Math.max(1, Math.round(image.naturalHeight * scale));
    const context = canvas.getContext('2d');
    if (!context) throw new Error('Your browser could not prepare the cover image.');
    context.fillStyle = '#f3efe5';
    context.fillRect(0, 0, canvas.width, canvas.height);
    context.drawImage(image, 0, 0, canvas.width, canvas.height);
    const dataUrl = canvas.toDataURL('image/jpeg', 0.95);
    // Free the pixel buffer promptly when creating large illustrated books.
    canvas.width = canvas.height = 1;
    return { ...placement, dataUrl, sourceWidth: image.naturalWidth, sourceHeight: image.naturalHeight };
  } finally { URL.revokeObjectURL(url); }
}

export interface PaperbackCoverResult {
  blob: Blob;
  warnings: string[];
  dimensions: ReturnType<typeof coverDimensions>;
}

export async function generatePaperbackCover(
  zip: JSZip, pageCount: number, options: PaperbackCoverOptions,
  title: string, author: string, cancelled: () => boolean = () => false,
): Promise<PaperbackCoverResult> {
  const check = () => { if (cancelled()) throw new DOMException('Cancelled', 'AbortError'); };
  check();
  const dimensions = coverDimensions(pageCount, options.paper);
  const original = await extractEpubCover(zip);
  check();
  const front = await prepareFrontImage(original);
  check();
  const result = await createPaperbackCover({
    title, author, backText: options.backText, printPages: dimensions.printPages,
    spine: dimensions.spine, frontImage: front.dataUrl, frontWidth: front.width, frontHeight: front.height,
  });
  check();
  const warnings = [...result.warnings];
  if (front.dpi < 300) warnings.unshift(
    `Your cover image may look blurry in print. Use a larger original image for a sharper cover. This image is ${front.sourceWidth} × ${front.sourceHeight} pixels; about ${Math.ceil(front.width * 300)} × ${Math.ceil(front.height * 300)} pixels would suit this cover.`,
  );
  if (dimensions.pdfPages !== dimensions.printPages) warnings.push(
    `The PDF has ${dimensions.pdfPages} pages. The cover allows for ${dimensions.printPages}, because KDP rounds up to an even page count.`,
  );
  return { blob: result.blob, dimensions, warnings };
}

// @vitest-environment node
import { describe, expect, it } from 'vitest';
import { coverDimensions, frontPlacement, characterCount, limitBackText } from './paperback-cover';
import { checkBackCoverText, createPaperbackCover } from 'book-pdf/cover';
import fs from 'node:fs';

describe('6x9 paperback cover', () => {
  it('uses the published KDP dimensions and rounds odd page counts up', () => {
    expect(coverDimensions(300, 'bw-cream')).toMatchObject({ spine: 0.75, width: 13, height: 9.25 });
    expect(coverDimensions(299, 'bw-cream').printPages).toBe(300);
    expect(coverDimensions(300, 'bw-white').spine).toBeCloseTo(0.6756, 6);
    expect(coverDimensions(300, 'standard-color').spine).toBeCloseTo(0.6756, 6);
    expect(coverDimensions(300, 'premium-color').spine).toBeCloseTo(0.7041, 6);
  });
  it('checks page limits for the chosen paper', () => {
    expect(() => coverDimensions(70, 'standard-color')).toThrow(/72–600/);
    expect(() => coverDimensions(777, 'bw-cream')).toThrow(/24–776/);
    expect(() => coverDimensions(829, 'bw-white')).toThrow(/24–828/);
    expect(() => coverDimensions(NaN, 'bw-white')).toThrow(/invalid/);
    expect(coverDimensions(827, 'bw-white').printPages).toBe(828);
  });
  it('preserves portrait, square, and landscape artwork and measures effective resolution', () => {
    expect(frontPlacement(1650, 2550)).toEqual({ width: 5.5, height: 8.5, dpi: 300 });
    expect(frontPlacement(1000, 1000)).toMatchObject({ width: 5.5, height: 5.5 });
    expect(frontPlacement(2200, 1100)).toMatchObject({ width: 5.5, height: 2.75 });
    expect(frontPlacement(600, 900).dpi).toBeLessThan(300);
  });
  it('counts spaces and Unicode characters without splitting surrogate pairs', () => {
    expect(characterCount('A 😀 B')).toBe(5);
    expect(characterCount(limitBackText('😀'.repeat(1600)))).toBe(1500);
  });
  it('checks actual 14-point text fit as well as character count', () => {
    expect(checkBackCoverText('A quiet story about the people who stay.')).toBeNull();
    expect(checkBackCoverText('x'.repeat(1501))).toMatch(/1,500/);
    expect(checkBackCoverText('A\n'.repeat(100))).toMatch(/more space/);
    expect(checkBackCoverText('A story 😀')).toMatch(/cannot print/);
    expect(checkBackCoverText('')).toBeNull();
  });
  it('renders a single cover with a thick spine and omits lettering on a thin one', async () => {
    const image = fs.readFileSync('public/images/sand-texture.jpg').toString('base64');
    const input = { title: 'The Quiet Valley', author: 'Clee Smith', backText: 'The road follows the river until it runs out of room.',
      printPages: 300, spine: 0.75, frontImage: `data:image/jpeg;base64,${image}`, frontWidth: 5.5, frontHeight: 8.25 };
    const thick = await createPaperbackCover(input);
    expect(thick.spineText).toBe(true);
    expect(thick.blob.size).toBeGreaterThan(1000);
    const thin = await createPaperbackCover({ ...input, printPages: 24, spine: 0.054048 });
    expect(thin.spineText).toBe(false);
    expect(thin.warnings[0]).toMatch(/left off/);
    if (process.env.COVER_TEST_OUTPUT) fs.writeFileSync(process.env.COVER_TEST_OUTPUT, new Uint8Array(await thick.blob.arrayBuffer()));
  });
});

'use client';

import React, { useEffect, useRef, useState } from 'react';
import JSZip from 'jszip';
import { GiBookPile } from 'react-icons/gi';
import type { Book } from '@/types/book';
import type { BookMetadata } from '@/libs/document';
import { useEnv } from '@/context/EnvContext';
import { getLocalBookFilename } from '@/utils/book';
import { getSpineItems, resolveTitlePageText } from '@/lib/epub-to-pdf';
import { BACK_COVER_LIMIT, characterCount, coverDimensions, limitBackText, type PaperChoice } from '@/lib/paperback-cover';
import type { PaperbackCoverResult } from '@/lib/paperback-cover-browser';

interface PaperbackCoverModalProps {
  book: Book;
  bookMeta: BookMetadata | null;
  isOpen: boolean;
  onClose: () => void;
}

const PaperbackCoverModal: React.FC<PaperbackCoverModalProps> = ({ book, bookMeta, isOpen, onClose }) => {
  const { envConfig } = useEnv();
  const [pages, setPages] = useState('');
  const [paper, setPaper] = useState<PaperChoice>('bw-white');
  const [backText, setBackText] = useState('');
  const [calculated, setCalculated] = useState<ReturnType<typeof coverDimensions> | null>(null);
  const [validation, setValidation] = useState<{ value: string; error: string | null } | null>(null);
  const [phase, setPhase] = useState<'options' | 'working' | 'ready'>('options');
  const [error, setError] = useState('');
  const [result, setResult] = useState<(PaperbackCoverResult & { url: string }) | null>(null);
  const request = useRef(0);
  const downloadUrl = useRef<string | null>(null);
  const pageInput = useRef<HTMLInputElement>(null);
  const interiorType = paper.startsWith('bw-') ? 'bw' : paper;
  const filename = (book.title || 'Book').replace(/[<>:"/\\|?*]/g, '').slice(0, 120).trim() || 'Book';

  const clearDownload = () => {
    if (downloadUrl.current) URL.revokeObjectURL(downloadUrl.current);
    downloadUrl.current = null;
  };

  useEffect(() => {
    request.current++;
    clearDownload();
    setResult(null);
    setError('');
    setPhase('options');
    return () => { request.current++; clearDownload(); };
  }, [isOpen]);

  useEffect(() => {
    if (isOpen && phase === 'options') pageInput.current?.focus();
  }, [isOpen, phase]);

  useEffect(() => {
    if (!isOpen || !calculated || phase !== 'options') return;
    let active = true;
    import('book-pdf/cover').then(({ checkBackCoverText }) => {
      if (active) setValidation({ value: backText, error: checkBackCoverText(backText) });
    }).catch(() => {
      if (active) setValidation({ value: backText, error: 'The cover lettering could not be prepared. Close this dialog and try again.' });
    });
    return () => { active = false; };
  }, [isOpen, calculated, phase, backText]);

  if (!isOpen) return null;

  let dimensions: ReturnType<typeof coverDimensions> | null = null;
  let pageError = '';
  if (pages.trim()) {
    try {
      if (!/^\d+$/.test(pages.trim())) throw new Error('Enter a whole number of pages.');
      dimensions = coverDimensions(Number(pages), paper);
    } catch (failure) { pageError = failure instanceof Error ? failure.message : 'Check the page count.'; }
  }

  const close = () => {
    request.current++;
    clearDownload();
    onClose();
  };
  const changePaper = (choice: PaperChoice) => {
    setPaper(choice);
    setCalculated(null);
    setValidation(null);
    setError('');
  };
  const createCover = async () => {
    if (!calculated || phase === 'working' || !validation || validation.value !== backText || validation.error) return;
    const generation = ++request.current;
    const cancelled = () => generation !== request.current;
    setPhase('working');
    setError('');
    clearDownload();
    setResult(null);
    try {
      const appService = await envConfig.getAppService();
      const file = await appService.openFile(getLocalBookFilename(book), 'Books');
      if (cancelled()) return;
      const zip = await JSZip.loadAsync(await file.arrayBuffer());
      if (cancelled()) return;
      const spinePaths = await getSpineItems(zip);
      const titlePage = await resolveTitlePageText(zip, spinePaths, { title: book.title || 'Untitled', subtitle: bookMeta?.subtitle });
      if (cancelled()) return;
      const { generatePaperbackCover } = await import('@/lib/paperback-cover-browser');
      if (cancelled()) return;
      const cover = await generatePaperbackCover(zip, calculated.pdfPages, { paper, backText }, titlePage.title, book.author || 'Unknown', cancelled);
      if (cancelled()) return;
      const url = URL.createObjectURL(cover.blob);
      downloadUrl.current = url;
      setResult({ ...cover, url });
      setPhase('ready');
    } catch (failure) {
      if (cancelled()) return;
      setError(failure instanceof Error ? failure.message : 'The cover could not be created.');
      setPhase('options');
    }
  };

  return (
    <div className='fixed inset-0 z-[60] flex items-center justify-center bg-black/50 p-4' onKeyDown={event => {
      if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); close(); }
    }}>
      <div role='dialog' aria-modal='true' aria-label='Paperback cover calculator' className='bg-base-100 w-full max-w-xl max-h-[90vh] overflow-y-auto rounded-lg p-6 shadow-xl'>
        <h3 className='flex items-center gap-2 text-lg font-semibold'><GiBookPile aria-hidden='true' /> Paperback cover calculator</h3>
        <p className='mt-2 text-sm text-base-content/70'>Create your 6×9 interior PDF first, then enter its total page count here.</p>
        <a className='link mt-2 inline-block text-sm' href='https://kdp.amazon.com/cover-calculator' target='_blank' rel='noreferrer'>Open KDP’s cover calculator</a>

        {phase === 'ready' && result ? (
          <div className='mt-5 space-y-4'>
            <p className='font-semibold'>Your paperback cover PDF is ready.</p>
            <p className='text-sm'>6 × 9 inches · {result.dimensions.pdfPages} interior pages</p>
            {result.warnings.length > 0 && <ul className='list-disc space-y-2 pl-5 text-sm'>{result.warnings.map(message => <li key={message}>{message}</li>)}</ul>}
            <div className='flex flex-wrap items-center gap-3'>
              <a className='btn btn-primary btn-sm' href={result.url} download={`${filename}-6x9-cover.pdf`}>Download cover PDF</a>
              <a className='link text-sm' href={result.url} target='_blank' rel='noreferrer'>View cover PDF</a>
            </div>
            <p className='text-sm text-base-content/70'>Use this cover with the PDF whose page count you entered. If that PDF changes, create a new cover using its new page count.</p>
            <div className='flex justify-end gap-2'>
              <button className='btn btn-ghost btn-sm' onClick={() => { clearDownload(); setResult(null); setPhase('options'); }}>Change cover details</button>
              <button className='btn btn-primary btn-sm' onClick={close}>Close</button>
            </div>
          </div>
        ) : (
          <form className='mt-5' noValidate onSubmit={event => { event.preventDefault(); void createCover(); }}>
            <fieldset disabled={phase === 'working'}>
              <legend className='mb-3 text-sm font-semibold'>Enter your book information</legend>
              <div className='grid grid-cols-1 gap-3 sm:grid-cols-2'>
                <label className='block text-sm'>Binding type
                  <input className='input input-bordered input-sm mt-1 w-full bg-base-200' value='Paperback' readOnly tabIndex={-1} />
                </label>
                <label className='block text-sm'>Interior type
                  <select className='select select-bordered select-sm mt-1 w-full' value={interiorType} onChange={event => changePaper(event.target.value === 'bw' ? 'bw-white' : event.target.value as PaperChoice)}>
                    <option value='bw'>Black &amp; white</option><option value='standard-color'>Standard color</option><option value='premium-color'>Premium color</option>
                  </select>
                </label>
                <label className='block text-sm'>Paper type
                  <select className='select select-bordered select-sm mt-1 w-full' value={paper === 'bw-cream' ? 'cream' : 'white'} disabled={interiorType !== 'bw'} onChange={event => changePaper(event.target.value === 'cream' ? 'bw-cream' : 'bw-white')}>
                    <option value='white'>White paper</option>{interiorType === 'bw' && <option value='cream'>Cream paper</option>}
                  </select>
                </label>
                <label className='block text-sm'>Reading direction
                  <input className='input input-bordered input-sm mt-1 w-full bg-base-200' value='Left to right' readOnly tabIndex={-1} />
                </label>
                <label className='block text-sm'>Measurement units
                  <input className='input input-bordered input-sm mt-1 w-full bg-base-200' value='Inches' readOnly tabIndex={-1} />
                </label>
                <label className='block text-sm'>Interior trim size
                  <input className='input input-bordered input-sm mt-1 w-full bg-base-200' value='6 × 9 inches' readOnly tabIndex={-1} />
                </label>
                <label className='block text-sm sm:col-span-2'>Page count
                  <input ref={pageInput} type='number' min='1' step='1' inputMode='numeric' className='input input-bordered input-sm mt-1 w-full' value={pages}
                    aria-describedby='cover-page-help' aria-invalid={!!pageError} onChange={event => { setPages(event.target.value); setCalculated(null); setValidation(null); setError(''); }} />
                </label>
              </div>
              <p id='cover-page-help' className='mt-2 text-xs text-base-content/70'>Use the PDF viewer’s total, including title pages and blank pages, rather than the last printed page number.</p>
              {pageError && <p role='alert' className='mt-2 text-sm text-error'>{pageError}</p>}
              <button type='button' className='btn btn-outline btn-sm mt-3' disabled={!dimensions} onClick={() => { setCalculated(dimensions); setValidation(null); setError(''); }}>Calculate dimensions</button>

              {calculated && (
                <div className='mt-5 border-t border-base-300 pt-4'>
                  <table className='mb-4 w-full text-sm' aria-label='Calculated cover dimensions'>
                    <tbody>
                      <tr><th className='py-1 text-left font-medium' scope='row'>Full cover, including bleed</th><td className='text-right'>{calculated.width.toFixed(4)} × {calculated.height.toFixed(4)} inches</td></tr>
                      <tr><th className='py-1 text-left font-medium' scope='row'>Spine width</th><td className='text-right'>{calculated.spine.toFixed(4)} inches</td></tr>
                      <tr><th className='py-1 text-left font-medium' scope='row'>Pages for printing</th><td className='text-right'>{calculated.printPages}</td></tr>
                    </tbody>
                  </table>
                  {calculated.printPages !== calculated.pdfPages && <p className='mb-3 text-xs text-base-content/70'>The cover allows for {calculated.printPages} pages because KDP rounds up to an even page count.</p>}
                  <p className='mb-3 text-sm text-base-content/70'>Uses this EPUB’s cover. The front, back, spine lettering, and space for KDP’s barcode are arranged automatically.</p>
                  <label className='block text-sm'>Back-cover text
                    <textarea className='textarea textarea-bordered mt-1 h-32 w-full text-base' value={backText} aria-describedby='cover-back-count'
                      onChange={event => { setBackText(limitBackText(event.target.value)); setValidation(null); }} />
                  </label>
                  <p id='cover-back-count' className='mt-1 text-xs text-base-content/70'>{characterCount(backText).toLocaleString()} / {BACK_COVER_LIMIT.toLocaleString()} characters, including spaces. Printed in 14-point EB Garamond.</p>
                  {validation?.error && <p role='alert' className='mt-2 text-sm text-error'>{validation.error}</p>}
                  <p className='mt-3 text-xs text-base-content/70'>Choose these same printing and paper options when publishing on KDP.</p>
                </div>
              )}
            </fieldset>
            {error && <p role='alert' className='mt-4 text-sm text-error'>{error}</p>}
            <div className='mt-5 flex items-center justify-end gap-2'>
              {phase === 'working' && <span role='status' className='mr-auto flex items-center gap-2 text-sm'><span className='loading loading-spinner loading-sm' />Creating your cover…</span>}
              <button type='button' className='btn btn-ghost btn-sm' onClick={close}>Cancel</button>
              {calculated && <button type='submit' className='btn btn-primary btn-sm' disabled={phase === 'working' || !validation || validation.value !== backText || !!validation.error}>Create cover PDF</button>}
            </div>
          </form>
        )}
      </div>
    </div>
  );
};

export default PaperbackCoverModal;

import React from 'react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react';
import type { Book } from '@/types/book';
import type { PaperbackCoverResult } from '@/lib/paperback-cover-browser';
import PaperbackCoverModal from './PaperbackCoverModal';
const mocked = vi.hoisted(() => ({ generate: vi.fn(), openFile: vi.fn(), createUrl: vi.fn(), revokeUrl: vi.fn() }));
vi.mock('@/context/EnvContext', () => ({ useEnv: () => ({ envConfig: { getAppService: async () => ({ openFile: mocked.openFile }) } }) }));
vi.mock('@/utils/book', () => ({ getLocalBookFilename: () => 'book.epub' }));
vi.mock('jszip', () => ({ default: { loadAsync: async () => ({ loadedEpub: true }) } }));
vi.mock('@/lib/epub-to-pdf', () => ({ getSpineItems: async () => ['chapter.xhtml'], resolveTitlePageText: async () => ({ title: 'Book title' }) }));
vi.mock('@/lib/paperback-cover-browser', () => ({ generatePaperbackCover: mocked.generate }));
const book = { hash: 'one', format: 'EPUB', title: 'Book title', author: 'Clee Smith', createdAt: 1, updatedAt: 1 } as Book;
const result = () => ({ blob: new Blob(['PDF'], { type: 'application/pdf' }), warnings: ['The image may look blurry in print.'], dimensions: { pdfPages: 300, printPages: 300, spine: 0.75, width: 13, height: 9.25 } });
const open = (onClose = vi.fn()) => render(<PaperbackCoverModal book={book} bookMeta={null} isOpen onClose={onClose} />);
const calculate = (pages = '300') => { fireEvent.change(screen.getByLabelText('Page count'), { target: { value: pages } }); fireEvent.click(screen.getByText('Calculate dimensions')); };
beforeEach(() => {
  vi.clearAllMocks();
  mocked.openFile.mockResolvedValue({ arrayBuffer: async () => new ArrayBuffer(0) });
  mocked.generate.mockResolvedValue(result());
  mocked.createUrl.mockReturnValue('blob:cover');
  vi.stubGlobal('URL', Object.assign(URL, { createObjectURL: mocked.createUrl, revokeObjectURL: mocked.revokeUrl }));
});
afterEach(() => { cleanup(); vi.unstubAllGlobals(); });
describe('separate paperback-cover calculator', () => {
  it('requires the PDF page count and recalculation after changing paper', () => {
    open();
    expect((screen.getByText('Calculate dimensions') as HTMLButtonElement).disabled).toBe(true);
    expect((screen.getByLabelText('Binding type') as HTMLInputElement).value).toBe('Paperback');
    expect((screen.getByLabelText('Interior trim size') as HTMLInputElement).value).toBe('6 × 9 inches');
    expect(screen.getByRole('link', { name: /KDP’s cover calculator/ }).getAttribute('href')).toBe('https://kdp.amazon.com/cover-calculator');
    calculate('301');
    expect(screen.getByRole('table')).toBeTruthy(); expect(screen.getByText('302')).toBeTruthy();
    fireEvent.change(screen.getByLabelText('Interior type'), { target: { value: 'standard-color' } });
    expect(screen.queryByRole('table')).toBeNull();
    expect((screen.getByLabelText('Paper type') as HTMLSelectElement).disabled).toBe(true);
    fireEvent.change(screen.getByLabelText('Page count'), { target: { value: '40' } });
    expect(screen.getByRole('alert').textContent).toContain('72–600');
    expect((screen.getByText('Calculate dimensions') as HTMLButtonElement).disabled).toBe(true);
  });
  it('creates a cover using the EPUB and count, preserving the warnings', async () => {
    const close = vi.fn(); open(close);
    fireEvent.change(screen.getByLabelText('Paper type'), { target: { value: 'cream' } }); calculate();
    expect(screen.getByText('0.7500 inches')).toBeTruthy();
    fireEvent.change(screen.getByLabelText('Back-cover text'), { target: { value: 'A quiet valley.' } });
    await waitFor(() => expect((screen.getByText('Create cover PDF') as HTMLButtonElement).disabled).toBe(false), { timeout: 5000 });
    fireEvent.click(screen.getByText('Create cover PDF'));
    await screen.findByRole('link', { name: 'Download cover PDF' });
    expect(mocked.openFile).toHaveBeenCalledWith('book.epub', 'Books');
    expect(mocked.generate).toHaveBeenCalledWith({ loadedEpub: true }, 300, { paper: 'bw-cream', backText: 'A quiet valley.' }, 'Book title', 'Clee Smith', expect.any(Function));
    expect(screen.queryByText('Download interior PDF')).toBeNull();
    expect(screen.getByText('The image may look blurry in print.')).toBeTruthy();
    fireEvent.click(screen.getByText('Close')); expect(close).toHaveBeenCalledOnce(); expect(mocked.revokeUrl).toHaveBeenCalledWith('blob:cover');
  });
  it('limits back text and rejects text that does not fit', async () => {
    open(); calculate();
    fireEvent.change(screen.getByLabelText('Back-cover text'), { target: { value: 'a'.repeat(1600) } });
    expect((screen.getByLabelText('Back-cover text') as HTMLTextAreaElement).value.length).toBe(1500);
    fireEvent.change(screen.getByLabelText('Back-cover text'), { target: { value: 'A\n'.repeat(70) } });
    expect((await screen.findByRole('alert')).textContent).toContain('Shorten it');
